//! The C3 M3 probe (plans/c3-m3 step 1): a screw on a hole's edge with
//! core commands only, before ADR-0038 lets a plugin issue them. On
//! `tests/docs/bracket`, a cylinder part made by a plugin feature type
//! (`probe.cylinder`, standing in for `fasteners.socket-head`), an
//! assembly holding the bracket and one cylinder per patterned hole, and a
//! fixed joint from each counterbore's top edge to the cylinder's end edge.
//!
//! What it found, on `arris` 0.8:
//!
//! - The counterbore's top edge is generated by the hole from the plate's
//!   top face and the counterbore's side, `edge:sweep.<plate>.end-cap/
//!   gen.<hole>[…]`. The pattern's copies are generated by the pattern, by
//!   copy: `gen.<pattern>[…/inst.<pattern>.1]` and `gen.<pattern>.1[…/
//!   inst.<pattern>.2]`. Each name survives the width, thickness and
//!   spacing edits below, so each joint resolves with no diagnostic.
//! - Arris orients each of those circles down the hole, into the plate
//!   (-z, the original and the copies alike). The cylinder's end edge is
//!   oriented along its extrusion, out of the cylinder. A fixed joint
//!   unflipped makes the two equal, which stands the cylinder on the
//!   plate. `flip` puts it in the hole, its end edge at the hole's top. The
//!   circle's orientation is Arris's choice and not a stated property, so
//!   a plugin should not read the side from it alone (plans/c3-m3,
//!   Findings).
//! - In `tests/docs/bracket` a width edit does not move the holes. The
//!   plate grows away from its fixed corner, and the `Top` datum plane the
//!   hole sketch stands on does not move (c1_accept, criterion 4). The
//!   plate's thickness moves every hole up by the change, and the pattern's
//!   spacing moves each copy by its index times the change. Each cylinder
//!   moves exactly with its hole.
//! - Saved with its result and opened without `probe.cylinder`, the
//!   cylinder is frozen (`plugin.frozen.missing`). Each joint still
//!   resolves on the frozen body's names, at the live pose exactly, and
//!   follows the same edits.

mod common;

use std::collections::BTreeMap;
use std::sync::Arc;

use arrix_core::{
    AssemblyId, ComponentId, CurveKey, DVec2, DVec3, Diagnostic, FeatureId, Frame, Id, IdMinter,
    MeshDetail, PartId, PersistentName, QuantityKind, SlotName,
};
use arrix_doc::{
    Anchor, Assembly, AuthorId, Command, Component, ComponentOf, Document, Evaluator, FeatureArgs,
    FeatureEdit, FeatureOutcome, FeatureRecord, FeatureType, FeatureTypeId, FrozenReason,
    JointKind, JointOutcome, MemorySource, Part, Pose, Registry, Session, TypeOutput, apply,
    expr::Expr, open,
};
use arrix_plugin_api::{
    FeatureOutput, FeatureTypeSpec, Kernel, OutputValue, ParamSpec, Profile, ProfileLoop, SlotKind,
    SlotOutput, SlotSpec,
};
use common::{Client, read_tree, registry, workspace};

const MM: f64 = 1e-3;
const LENGTH: f64 = 10.0 * MM;
const BRACKET: &str = "8E4ZYYF80N5EM";
const WIDTH: &str = "4SZ1VMCFJ1YDG";
const THICKNESS: &str = "D1BPZWKQ716XG";
const PATTERN: &str = "E635NVKB74361";
/// The counterbore's radius, 8 mm across.
const CB_RADIUS: f64 = 4.0 * MM;

/// `probe.cylinder`, a stand-in for `fasteners.socket-head`: a circle of
/// `radius` on the world's XY plane extruded `length` up +z.
struct Cylinder(FeatureTypeSpec);

impl Cylinder {
    fn new() -> Self {
        let param = |name: &str, default: &str| ParamSpec {
            name: name.into(),
            title: name.into(),
            kind: QuantityKind::Length,
            default: default.into(),
            shown_when: None,
        };
        Cylinder(FeatureTypeSpec {
            id: "probe.cylinder".into(),
            version: 1,
            title: "Cylinder".into(),
            params: vec![param("radius", "3.5 mm"), param("length", "10 mm")],
            inputs: vec![],
            outputs: vec![SlotSpec {
                name: SlotName::new("body").unwrap(),
                kind: SlotKind::Body,
                modifies: None,
            }],
            choices: vec![],
        })
    }
}

impl FeatureType for Cylinder {
    fn spec(&self) -> &FeatureTypeSpec {
        &self.0
    }

    fn evaluate(
        &self,
        kernel: &mut dyn Kernel,
        args: &FeatureArgs,
    ) -> Result<TypeOutput, Diagnostic> {
        let circle = ProfileLoop::Circle {
            key: CurveKey(Id(1)),
            center: DVec2::ZERO,
            radius: args.param("radius").unwrap(),
        };
        let profile = Profile::new(Frame::WORLD_XY, circle, vec![]).unwrap();
        let body = kernel.extrude(&profile, args.param("length").unwrap())?;
        Ok(FeatureOutput {
            slots: vec![SlotOutput {
                name: SlotName::new("body").unwrap(),
                value: OutputValue::Body(body),
            }],
            tool: None,
        }
        .into())
    }

    fn plugin_version(&self) -> Option<&str> {
        Some("0.1.0")
    }
}

fn with_cylinder() -> Registry {
    let mut r = registry();
    r.register(Arc::new(Cylinder::new())).unwrap();
    r
}

fn e(text: &str) -> Expr {
    Expr::parse(text).unwrap()
}

fn bracket() -> Document {
    let mut files = BTreeMap::new();
    read_tree(&workspace().join("tests/docs/bracket"), "", &mut files);
    open(&MemorySource(files)).expect("the bracket opens")
}

fn id<T: std::str::FromStr>(text: &str) -> T
where
    T::Err: std::fmt::Debug,
{
    text.parse().unwrap()
}

/// A circular edge of a mesh: its name, centre and radius, read off its
/// polyline.
#[derive(Clone, Debug)]
struct Circle {
    name: PersistentName,
    center: DVec3,
    radius: f64,
}

/// Every closed edge of `part`'s final body whose polyline lies on a
/// circle, by name.
fn circles(evaluator: &mut Evaluator, part: PartId) -> Vec<Circle> {
    let finals: Vec<_> = evaluator
        .final_bodies()
        .iter()
        .filter(|b| b.part == part)
        .cloned()
        .collect();
    let mut out = Vec::new();
    for body in finals {
        let mesh = evaluator.mesh(&body, MeshDetail::Refined).unwrap();
        for edge in &mesh.edges {
            let points: Vec<DVec3> = mesh.edge_points[edge.range()]
                .iter()
                .map(|&p| mesh.world(p))
                .collect();
            let closed = (points[0] - points[points.len() - 1]).length() < 1e-6;
            if !closed || points.len() < 8 {
                continue;
            }
            let ring = &points[..points.len() - 1];
            let center = ring.iter().copied().sum::<DVec3>() / ring.len() as f64;
            let radius = (ring[0] - center).length();
            if ring
                .iter()
                .all(|p| ((*p - center).length() - radius).abs() < 1e-6)
            {
                out.push(Circle {
                    name: edge.name.clone(),
                    center,
                    radius,
                });
            }
        }
    }
    out
}

/// The counterbores' top edges, on the plate's top: the 8 mm circles
/// highest up, ordered along y.
fn hole_tops(circles: &[Circle]) -> Vec<Circle> {
    let cb: Vec<&Circle> = circles
        .iter()
        .filter(|c| (c.radius - CB_RADIUS).abs() < 1e-5)
        .collect();
    let top = cb.iter().map(|c| c.center.z).fold(f64::MIN, f64::max);
    let mut out: Vec<Circle> = cb
        .into_iter()
        .filter(|c| (c.center.z - top).abs() < 1e-9)
        .cloned()
        .collect();
    out.sort_by(|a, b| a.center.y.total_cmp(&b.center.y));
    out
}

struct Ids {
    author: AuthorId,
    part: PartId,
    feature: FeatureId,
    assembly: AssemblyId,
    bracket: ComponentId,
    screws: Vec<(ComponentId, arrix_core::JointId)>,
}

impl Ids {
    fn new(holes: usize) -> Self {
        let mut m = IdMinter::new(3003);
        Ids {
            author: AuthorId(m.next_id()),
            part: m.mint(),
            feature: m.mint(),
            assembly: m.mint(),
            bracket: m.mint(),
            screws: (0..holes).map(|_| (m.mint(), m.mint())).collect(),
        }
    }

    fn end_edge(&self) -> PersistentName {
        format!("edge:sweep.{}.end-edge.0000000000001", self.feature)
            .parse()
            .unwrap()
    }
}

fn cylinder_part(i: &Ids) -> Command {
    let record = FeatureRecord {
        id: i.feature,
        type_id: FeatureTypeId::new("probe.cylinder").unwrap(),
        type_version: 1,
        name: "Cylinder".into(),
        params: [
            ("length".into(), e("10 mm")),
            ("radius".into(), e("3.5 mm")),
        ]
        .into(),
        choices: BTreeMap::new(),
        inputs: BTreeMap::new(),
        suppressed: false,
        sketch: None,
        frozen: None,
        file: None,
    };
    Command::AddPart {
        part: Part {
            id: i.part,
            name: "Cylinder".into(),
            history: vec![i.feature],
            features: [(i.feature, record)].into(),
            rollback: None,
            material: None,
            body_materials: Default::default(),
        },
    }
}

/// The bracket grounded at the origin and a cylinder in each hole by a
/// fixed joint, the hole's top edge to the cylinder's end edge.
fn assembly(i: &Ids, holes: &[Circle], flip: bool) -> Command {
    let zero = Pose {
        position: ["0 mm", "0 mm", "0 mm"].map(e),
        rpy: ["0 deg", "0 deg", "0 deg"].map(e),
    };
    let mut components = BTreeMap::new();
    components.insert(
        i.bracket,
        Component {
            id: i.bracket,
            name: "bracket".into(),
            of: ComponentOf::Part(id(BRACKET)),
            pose: Some(zero),
        },
    );
    let mut joints = BTreeMap::new();
    for (n, (hole, &(c, j))) in holes.iter().zip(&i.screws).enumerate() {
        components.insert(
            c,
            Component {
                id: c,
                name: format!("cylinder {}", n + 1),
                of: ComponentOf::Part(i.part),
                pose: None,
            },
        );
        joints.insert(
            j,
            arrix_doc::Joint {
                id: j,
                name: format!("hole {}", n + 1),
                kind: JointKind::Fixed,
                parent: Anchor {
                    path: vec![i.bracket],
                    axis: hole.name.clone(),
                    origin: None,
                },
                child: Anchor {
                    path: vec![c],
                    axis: i.end_edge(),
                    origin: None,
                },
                value: e("0 deg"),
                offset: e("0 deg"),
                limits: None,
                flip,
            },
        );
    }
    Command::AddAssembly {
        assembly: Assembly {
            id: i.assembly,
            name: "screwed".into(),
            components,
            joints,
        },
    }
}

fn applied(doc: &Document, command: &Command) -> Document {
    apply(doc, command)
        .unwrap_or_else(|e| panic!("{command:?}: {e}"))
        .document
}

/// Each cylinder's pose and its joint's parent frame (the hole edge's,
/// in the world), its joint resolved.
fn poses(evaluator: &mut Evaluator, doc: &Document, i: &Ids) -> Vec<(Frame, Frame)> {
    let evaluation = evaluator.evaluate(doc);
    let outcome = &evaluation.assemblies[&i.assembly];
    i.screws
        .iter()
        .map(|(c, j)| {
            let JointOutcome::Ok {
                parent,
                diagnostics,
                ..
            } = &outcome.joints[j]
            else {
                panic!("{:?}", outcome.joints[j])
            };
            assert!(diagnostics.is_empty(), "{diagnostics:?}");
            (outcome.pose(&[*c]).unwrap(), *parent)
        })
        .collect()
}

/// The plate's top, where every counterbore starts.
const TOP: f64 = 5.0 * MM;

#[track_caller]
fn near(a: DVec3, b: DVec3) {
    assert!((a - b).length() < 1e-12, "{a} vs {b}");
}

/// How far an edit moves the hole of an index.
type Move = fn(usize) -> DVec3;

/// Each edit moves each hole by what `moves` gives for the hole's index,
/// and each cylinder exactly with its hole.
fn follows(evaluator: &mut Evaluator, doc: &Document, i: &Ids) {
    let before = poses(evaluator, doc, i);
    let moves: [(Command, Move); 3] = [
        (set(WIDTH, "70 mm"), |_| DVec3::ZERO),
        (set(THICKNESS, "6 mm"), |_| DVec3::Z * MM),
        (spacing("12 mm"), |n| DVec3::Y * 2.0 * MM * n as f64),
    ];
    for (edit, moved) in moves {
        let after = poses(evaluator, &applied(doc, &edit), i);
        for (n, (b, a)) in before.iter().zip(&after).enumerate() {
            near(a.1.origin() - b.1.origin(), moved(n));
            near(a.0.origin() - b.0.origin(), moved(n));
        }
    }
}

fn set(param: &str, expr: &str) -> Command {
    Command::SetParam {
        param: id(param),
        expr: e(expr),
    }
}

fn spacing(expr: &str) -> Command {
    Command::EditFeature {
        feature: id(PATTERN),
        edit: FeatureEdit {
            params: [("spacing".into(), Some(e(expr)))].into(),
            ..FeatureEdit::default()
        },
    }
}

#[test]
fn a_cylinder_on_each_patterned_holes_edge() {
    let doc = bracket();
    let mut evaluator = Evaluator::new(with_cylinder());
    evaluator.evaluate(&doc);
    let holes = hole_tops(&circles(&mut evaluator, id(BRACKET)));
    let side = |f: &str, s: &str| {
        format!(
            "face:sweep.6YGYXVGFE9Z3Z.end-cap,face:revolve.CETME0KJFBN9F.side.0000000000002{s}{f}"
        )
    };
    let names: Vec<String> = holes.iter().map(|h| h.name.to_string()).collect();
    assert_eq!(
        names,
        [
            format!(
                "edge:sweep.6YGYXVGFE9Z3Z.end-cap/gen.CETME0KJFBN9F[{}]",
                side("", "")
            ),
            format!(
                "edge:sweep.6YGYXVGFE9Z3Z.end-cap/gen.{PATTERN}[{}]",
                side("1", &format!("/inst.{PATTERN}."))
            ),
            format!(
                "edge:sweep.6YGYXVGFE9Z3Z.end-cap/gen.{PATTERN}.1[{}]",
                side("2", &format!("/inst.{PATTERN}."))
            ),
        ]
    );

    let i = Ids::new(holes.len());
    let base = applied(&doc, &cylinder_part(&i));
    for flip in [false, true] {
        let doc = applied(&base, &assembly(&i, &holes, flip));
        for (n, (pose, parent)) in poses(&mut evaluator, &doc, &i).into_iter().enumerate() {
            let at = DVec3::new(20.0, -12.0 + 10.0 * n as f64, 5.0) * MM;
            near(parent.origin(), at);
            near(parent.z_axis(), -DVec3::Z);
            // The cylinder spans its origin to `length` up its own z, its
            // end edge at the hole's top: on the plate, or in the hole.
            let end = pose.origin() + pose.z_axis() * LENGTH;
            near(end, at);
            let below = if flip { TOP - LENGTH } else { TOP };
            assert!(
                (pose.origin().z.min(end.z) - below).abs() < 1e-12,
                "flip {flip}"
            );
        }
    }

    let doc = applied(&base, &assembly(&i, &holes, true));
    follows(&mut evaluator, &doc, &i);

    // Saved with its result, opened without `probe.cylinder`.
    let c = Client::of_document(i.author, doc.clone(), with_cylinder());
    let reopened = open(&c.session.save()).unwrap();
    let mut without = Evaluator::new(registry());
    let evaluation = without.evaluate(&reopened);
    let Some(FeatureOutcome::Ok {
        frozen: Some(frozen),
        ..
    }) = evaluation.outcome(i.feature)
    else {
        panic!("{:?}", evaluation.outcome(i.feature))
    };
    assert_eq!(frozen.reason, FrozenReason::Missing);
    let live = poses(&mut evaluator, &doc, &i);
    for (f, l) in poses(&mut without, &reopened, &i).iter().zip(&live) {
        near(f.0.origin(), l.0.origin());
        near(f.0.z_axis(), l.0.z_axis());
    }
    follows(&mut without, &reopened, &i);
}
